import React, { useState } from 'react';
import '../styles/login-page.css';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';


function LoginPage() {
  const navigate = useNavigate(); // Initialize navigate
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");



  const handleLogin = async () => {
    // Add your login logic here (e.g., form validation or authentication)
    // If login is successful, navigate to the home page

    const result = await axios.post(`http://localhost:5001/api/authentication/login`, {
      inputedUsername: username, inputedPassword: password
    });
    //Checking if user has right credentials

    //If they are right log user in 
    if (result.data.trim === "success") {
      console.log('YEee');
      navigate('/home');
    }

    //If they are not right show user error message
    else {

    }



  };
  return (
    <div className="login-container">
      <div className="login-box">
        <h1 className="login-title">Smart Personal Finance Manager</h1>
        <div className="input-container">
          <label className="input-label" htmlFor="username">
            Username
          </label>
          <input
            type="text"
            id="username"
            placeholder="Enter your username"
            className="input-field"
            onChange={
              (e) => setUsername(e.target.value)
            }
          />
        </div>
        <div className="input-container">
          <label className="input-label" htmlFor="password">
            Password
          </label>
          <input
            type="password"
            id="password"
            placeholder="Enter your password"
            className="input-field"
            onChange={
              (e) => setPassword(e.target.value)
            }
          />
        </div>
        <div className="button-container">
          <button className="login-button" onClick={handleLogin}>Login</button>
        </div>
      </div>
    </div>
  );
}

export default LoginPage;
